def get_instance_info(conn) -> dict[str, Any]:
        """Identity of the FreeCAD addon answering on this port."""
        info = conn.server.get_instance_info()
        if isinstance(info, Mapping):
            raw_capabilities = info.get("rpc_method_capabilities")
            capabilities = (
                dict(raw_capabilities)
                if isinstance(raw_capabilities, Mapping)
                else {}
            )
            identity_lock = getattr(conn, "_identity_lock", None)
            if identity_lock is None:
                conn._rpc_method_capabilities = capabilities
                conn._rpc_method_capabilities_loaded = True
            else:
                with identity_lock:
                    conn._rpc_method_capabilities = capabilities
                    conn._rpc_method_capabilities_loaded = True
        return info


def supports_rpc_parameter(conn, method: str, parameter: str) -> bool | None:
        """Return advertised parameter support, or ``None`` if unobservable.

        An addon that answers ``get_instance_info`` without the capability map
        predates parameter advertisement. For newly introduced parameters that
        is authoritative absence, allowing the caller to select a compatibility
        path before starting a mutation.
        """
        with conn._identity_lock:
            loaded = conn._rpc_method_capabilities_loaded
        if not loaded:
            try:
                conn.get_instance_info()
            except Exception:
                return None

        with conn._identity_lock:
            method_capability = conn._rpc_method_capabilities.get(method)
        if not isinstance(method_capability, Mapping):
            return False
        parameters = method_capability.get("parameters")
        if not isinstance(parameters, (list, tuple, set, frozenset)):
            return False
        return parameter in parameters


def verify_instance(conn) -> dict[str, Any]:
        """Confirm the addon on this port is the expected instance.

        No-op (returns the reported info) when no ``expected_instance_id`` was
        configured. Raises ``InstanceMismatchError`` when the id differs, so a
        client configured for an isolated instance never silently drives the
        wrong FreeCAD when several addons listen on nearby ports.
        """
        info = conn.get_instance_info()
        if not conn._expected_instance_id:
            return info
        actual = (info or {}).get("instance_id")
        if actual != conn._expected_instance_id:
            raise InstanceMismatchError(
                f"Expected FreeCAD instance '{conn._expected_instance_id}' on "
                f"{conn._uri} but the addon reported '{actual}'. Refusing to "
                "drive the wrong instance."
            )
        return info


